package com.booksyde.service;
import com.booksyde.dto.response.*; import com.booksyde.entity.*; import com.booksyde.exception.*; import com.booksyde.repository.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class MarketplaceService { private final MarketplaceListingRepository listings; private final MarketplaceOrderRepository orders; private final MarketplaceOrderItemRepository items; public MarketplaceService(MarketplaceListingRepository l,MarketplaceOrderRepository o,MarketplaceOrderItemRepository i){listings=l;orders=o;items=i;} @Transactional(readOnly=true) public List<MarketplaceListingResponse> publicListings(){return listings.findAllByActiveTrueOrderByCreatedAtDesc().stream().map(this::listing).toList();} @Transactional(readOnly=true) public List<MarketplaceListingResponse> sellerListings(UUID seller){return listings.findAllBySellerIdOrderByCreatedAtDesc(seller).stream().map(this::listing).toList();} @Transactional(readOnly=true) public List<MarketplaceOrderResponse> buyerOrders(UUID buyer){return orders.findAllByBuyerIdOrderByCreatedAtDesc(buyer).stream().map(this::order).toList();} @Transactional(readOnly=true) public List<MarketplaceOrderResponse> sellerOrders(UUID seller){return orders.findAllBySellerIdOrderByCreatedAtDesc(seller).stream().map(this::order).toList();} @Transactional(readOnly=true) public MarketplaceOrderEntity ownedOrder(UUID id,UUID buyer){var o=orders.findById(id).orElseThrow(()->new ResourceNotFoundException("Pedido não encontrado."));if(!o.getBuyerId().equals(buyer))throw new ForbiddenException("Pedido não pertence ao usuário autenticado.");return o;} @Transactional(readOnly=true) public List<MarketplaceOrderItemEntity> orderItems(UUID id){return items.findAllByOrderIdOrderById(id);} private MarketplaceListingResponse listing(MarketplaceListingEntity x){return new MarketplaceListingResponse(x.getId(),x.getSellerId(),x.getMangaId(),x.getTitle(),x.getAuthor(),x.getCategory(),x.getCoverUrl(),x.getPriceCents(),x.getCurrency(),x.getTargetType(),x.getWorkType());} private MarketplaceOrderResponse order(MarketplaceOrderEntity x){return new MarketplaceOrderResponse(x.getId(),x.getBuyerId(),x.getSellerId(),x.getStatus(),x.getTotalCents(),x.getCurrency(),x.getStripeEnvironment(),x.getCheckoutUrl(),x.getPaidAt(),x.getCreatedAt());}}
